var I=[];
I.push(
{c:0,en:"ترجمه‌ها و تفسیرهای فارسی قرآن",tr:"Kur’an’ın Farsça tercüme ve tefsirleri",
v:[["ترجمه","tercüme, çeviri","این ترجمه بسیار روان است.","Bu tercüme çok akıcı.","tarjome"],
["تفسیر","tefsir","تفسیر میبدی به فارسی نوشته شده است.","Meybüdî tefsiri Farsça yazılmıştır.","tafsir"],
["کهن","eski, kadim","این کتاب یکی از کهن‌ترین متن‌های فارسی است.","Bu kitap en eski Farsça metinlerden biridir.","kohan"],
["عالِم (ج. علما)","âlim","علمای ماوراءالنهر اجازهٔ ترجمه را دادند.","Mâverâünnehir âlimleri tercümeye izin verdi.","âlem"],
["نثر","nesir","نثر این دوره ساده و زیباست.","Bu dönemin nesri sade ve güzeldir.","nasr"],
["عرفانی","irfani, tasavvufi","میبدی برای هر آیه تفسیری عرفانی هم آورده است.","Meybüdî her ayet için tasavvufi bir yorum da getirmiştir.","erfâni"],
["واژه","kelime","او برای هر واژهٔ عربی معادلی فارسی پیدا کرد.","Her Arapça kelime için Farsça bir karşılık buldu.","vâje"],
["میراث","miras","این ترجمه‌ها میراث مشترک فارسی‌زبانان است.","Bu tercümeler Farsça konuşanların ortak mirasıdır.","mirâs"]],
p:[[["فارسی پس از عربی مهم‌ترین زبان فرهنگ اسلامی است و ترجمهٔ قرآن به آن تاریخی طولانی دارد.","Farsça Arapçadan sonra İslam kültürünün en önemli dilidir ve Kur’an’ın bu dile tercümesinin uzun bir tarihi vardır."],["در قرن چهارم هجری، در زمان سامانیان، تفسیر بزرگ طبری از عربی به فارسی ترجمه شد.","Hicri dördüncü yüzyılda, Sâmânîler zamanında, Taberî’nin büyük tefsiri Arapçadan Farsçaya çevrildi."],["در مقدمهٔ این کتاب آمده است که امیر سامانی پیش از ترجمه، از علمای ماوراءالنهر اجازه گرفت.","Bu kitabın önsözünde Sâmânî emirinin tercümeden önce Mâverâünnehir âlimlerinden izin aldığı anlatılır."]],
[["این ترجمه که به «ترجمهٔ تفسیر طبری» معروف است، یکی از کهن‌ترین نمونه‌های نثر فارسی است.","“Taberî Tefsiri Tercümesi” diye bilinen bu eser, Fars nesrinin en eski örneklerinden biridir."],["مترجمان کوشیدند برای واژه‌های قرآنی معادل‌های فارسی ساده پیدا کنند.","Mütercimler Kur’an kelimeleri için sade Farsça karşılıklar bulmaya çalıştı."],["به همین دلیل، این متن برای پژوهشگران زبان فارسی نیز بسیار ارزشمند است.","Bu yüzden bu metin Fars dili araştırmacıları için de çok değerlidir."]],
[["دو قرن بعد، رشیدالدین میبدی تفسیر «کشف الاسرار و عدة الابرار» را به فارسی نوشت.","İki yüzyıl sonra Reşîdüddîn Meybüdî Keşfü’l-esrâr ve iddetü’l-ebrâr tefsirini Farsça yazdı."],["میبدی هر آیه را در سه نوبت شرح داده است: ترجمه، تفسیر ظاهری و تفسیر عرفانی.","Meybüdî her ayeti üç aşamada açıklar: tercüme, zâhirî tefsir ve irfani tefsir."],["این روش نشان می‌دهد که در سنت فارسی، فهم قرآن با زبان دل و ادب نیز همراه بوده است.","Bu yöntem, Fars geleneğinde Kur’an’ı anlamanın gönül ve edep diliyle de birlikte yürüdüğünü gösterir."]]],
q:[["ترجمهٔ تفسیر طبری در زمان سامانیان انجام شد.",true],["میبدی تفسیر خود را به عربی نوشت.",false],["در کشف الاسرار هر آیه در سه نوبت شرح داده شده است.",true]],
dt:["گفت‌وگو در کتابخانه","Kerem, kütüphaneci Ahmedî Bey’e Farsça tefsirleri soruyor."],
d:[["کرم","ببخشید آقا، دنبال یک تفسیر فارسی برای شروع هستم.","Affedersiniz, başlamak için Farsça bir tefsir arıyorum."],
["آقای احمدی","برای شروع، کشف الاسرار میبدی را پیشنهاد می‌کنم؛ نثرش زیباست.","Başlangıç için Meybüdî’nin Keşfü’l-esrâr’ını öneririm; nesri çok güzel."],
["کرم","سخت نیست؟ فارسی من هنوز در سطح متوسط است.","Zor değil mi? Farsçam henüz orta seviyede."],
["آقای احمدی","بخش ترجمه‌اش ساده است. از همان شروع کن و کم‌کم جلو برو.","Tercüme kısmı sade. Oradan başla, yavaş yavaş ilerle."],
["کرم","ترجمهٔ تفسیر طبری را هم دارید؟","Taberî Tefsiri Tercümesi de var mı?"],
["آقای احمدی","بله، در قفسهٔ متون کهن. ولی برای خواندنش باید با فارسی قدیم آشنا باشی.","Evet, eski metinler rafında. Ama okumak için eski Farsçayı tanıman gerekir."],
["کرم","پس اول میبدی را می‌خوانم، بعد سراغ طبری می‌روم.","O zaman önce Meybüdî’yi okuyup sonra Taberî’ye geçeceğim."],
["آقای احمدی","تصمیم درستی است. کارت کتابخانه داری؟","Doğru karar. Kütüphane kartın var mı?"]],
g:{t:"Bileşik cümle: که, تا, پس از / پیش از",x:"Akademik Farsçada zaman ilişkileri edatla kurulur:\nپیش از + isim / پیش از اینکه + dilek kipi = “-den önce”\nپس از + isim / پس از اینکه + geçmiş = “-den sonra”\nکه ile isim cümlesi: آمده است که … (… diye anlatılır).",
e:[["پیش از ترجمه، از علما اجازه گرفت.","Tercümeden önce âlimlerden izin aldı."],["پس از سامانیان، این سنت ادامه یافت.","Sâmânîlerden sonra bu gelenek sürdü."],["در مقدمه آمده است که امیر اجازه گرفت.","Önsözde emirin izin aldığı anlatılır."],["پیش از اینکه شروع کنی، فارسی قدیم را بشناس.","Başlamadan önce eski Farsçayı tanı."]]}}
);
